// === Tab: mySketch ===
// For the #WCCChallenge, theme: "cat".
// I've been having fun this week with p5's oscillators and filters,
// which can easily make a lot of noise: https://openprocessing.org/sketch/2054759
// A specific sound, like a cat's purring, is significantly more difficult to achieve.
// Here, I've settled on a sawtooth wave, a low pass filter, and a slight delay.

var osc0;
var purring = false;
var purr = 0;
var tpurr = 0;

function setup() {
	createCanvas(windowWidth, windowHeight);
	configureSound();
}

function configureSound() {
	osc0 = new p5.Oscillator('sawtooth');
	filt = new p5.LowPass();
	filt.res(18);
	filt.gain(0.15);
	delay = new p5.Delay(0.75);
	osc0.disconnect();
	osc0.connect(filt);
	delay.process(osc0, 0.1, 0.1);
}

function draw() {
	background(0);
	purr = lerp(purr, tpurr, 0.1);
	fill(200 * (1 - purr));
	noStroke();
	textAlign(CENTER, CENTER);
	textSize(height / 12);
	text('click to pet the kitty!', width / 2, height / 16);
	// modulate frequency and amplitude of purring noise 
	let dv = 16 + 4 * noise(frameCount / 500);
	osc0.freq(16 + 8 * (abs(sin(frameCount / dv)))); 
	osc0.amp(max(0.01, sin(frameCount / dv) / 3) * purr);
	drawTail();
}

function drawTail() {
	let colorA = color('rgba(255,165,0,0.6)');
	let colorB = color('rgba(255,255,255,0.6)');
	for (let y = height * 1.1; y > height / 2; y -= height / 60) {
		let wave = map(y, height, height / 4, 0, QUARTER_PI);
		let col = lerpColor(colorA, colorB, map(y, height, height / 3, 0, 1));
		let len = cos(wave) * (height / 4);
		let ang = (566/height) * (0.55 - noise( (y / 300) + frameCount / 100)) / 24;
		let spread = 1.75 - noise((y / 1000) + frameCount / 200)*1.25;
		let num = map(y, height, height / 2, 48, 96);
		drawSegment(width / 2, y, ang, len, col, spread, num);
	}
}

function drawSegment(x, y, ang, len, col, spread, num) {
	stroke(col);
	rotate(-ang * num / 48);
	for (let a = -PI / 3; a < PI / 3; a += (Math.max(0.001, Math.abs(PI / num)) || 1)) {
		push();
		translate(x, y);
		rotate(a * spread);
		strokeWeight(cos(a) * len / 120);
		line(0, 0, 0, -len * cos(a));
		pop();
	}
}

function mouseClicked() {
	purring = !purring;
	if (purring) {
		osc0.start()
		tpurr = 1;
	} else {
		tpurr = 0;
	}
}
